def tr_upper(s):
    """Türkçe kurallarıyla büyük harfe çevir."""
    result = []
    for ch in s:
        if ch == 'i':
            result.append('I')
        elif ch == 'ı':
            result.append('İ')
        else:
            result.append(ch.upper())
    return ''.join(result)

